def transform(grid):
    n = len(grid)
    h = n // 2
    color = grid[h][h]
    quadrants = [
        (range(h), range(h), [(h - i, h - i) for i in range(h + 1)]),
        (range(h), range(h + 1, n), [(h - i, h + i) for i in range(h + 1)]),
        (range(h + 1, n), range(h), [(h + i, h - i) for i in range(h + 1)]),
        (range(h + 1, n), range(h + 1, n), [(h + i, h + i) for i in range(h + 1)])
    ]
    out = [[7] * n for _ in range(n)]
    for rs, cs, diagonal in quadrants:
        if any(grid[r][c] == color for r in rs for c in cs):
            for r, c in diagonal:
                out[r][c] = color
            break
    return out
